                    alignItems: 'center',
                    justifyContent: 'center',
                    color: kpi.color,
                    fontSize: 18,
                  }}
                >
                  {kpi.icon}
                </div>
                <div>
                  <Text type="secondary" style={{ fontSize: 11 }}>
