          <NamespaceSelector
            clusterId={clusterId}
            value={namespace}
            onChange={setNamespace}
            style={{ width: 200 }}
          />
        }
      />

      <YamlDrawer
        clusterId={clusterId}
        resourceType="replicasets"
        namespace={yamlDrawer.namespace}
        name={yamlDrawer.name}
        open={yamlDrawer.open}
        onClose={yamlDrawer.closeYaml}
      />
      <Drawer
        title="ReplicaSet 详情"
        open={!!detailRS}
        onClose={() => setDetailRS(null)}
        width={600}
