        pagination={{ defaultPageSize: 20, showSizeChanger: true, showTotal: (t) => `共 ${t} 条` }}
        scroll={{ x: 700 }}
        headerTitle={
          <NamespaceSelector
            clusterId={clusterId}
            value={namespace}
            onChange={setNamespace}
            style={{ width: 200 }}
          />
        }
      />

      {/* 详情抽屉 */}
      <Drawer
        title={`ServiceAccount 详情 - ${detailSA?.name}`}
        open={!!detailSA}
        onClose={() => setDetailSA(null)}
        width={640}
        destroyOnClose
