      queryClient.invalidateQueries({ queryKey: ['k8s-clusterrolebindings', clusterId] })
    },
  })

  const rbColumns: ProColumns<RBACRoleBinding>[] = [
    { title: '名称', dataIndex: 'name', ellipsis: true, copyable: true },
