      title: '命名空间',
      dataIndex: 'namespace',
      width: 140,
      ellipsis: true,
      render: (_, r) => <EllipsisText text={r.namespace || namespace} tag />,
    },
    {
      title: '角色',
      dataIndex: 'roleRef',
      width: 150,
      search: false,
      render: (_, record) => (
        <Tag color="blue">
          {typeof record.roleRef === 'string' ? record.roleRef : record.roleRef?.name || '-'}
        </Tag>
      ),
    },
    {
      title: '主题',
      dataIndex: 'subjects',
      width: 200,
      ellipsis: true,
      search: false,
      render: (_, record) =>
        (record.subjects || []).map((s) => (
          <Tag key={typeof s === 'string' ? s : s.name}>
            {typeof s === 'string' ? s : `${s.kind}/${s.name}`}
          </Tag>
        )),
    },
    {
      title: '创建时间',
      dataIndex: 'createdAt',
      width: 180,
      search: false,
      render: (_, record) => formatDate(record.createdAt),
    },
